awk -F',' '
{
    stock = $3
    action = $2
    count = $4

    if (action == "Purchase") {
        bought[stock] += count
        ever_bought[stock] = "true"
    } else if (action == "Sell") {
        sold[stock] += count
        ever_sold[stock] = "true"
    }
}
END {
    for (stock in bought) {
        if (!(stock in sold)) sold[stock] = 0
        if (!(stock in ever_sold)) ever_sold[stock] = "false"
    }
    for (stock in sold) {
        if (!(stock in bought)) bought[stock] = 0
        if (!(stock in ever_bought)) ever_bought[stock] = "false"
    }

    for (stock in bought) {
        net = bought[stock] - sold[stock]
        print stock "," bought[stock] "," sold[stock] "," net "," ever_bought[stock] "," ever_sold[stock]
    }
    for (stock in sold) {
        if (!(stock in bought)) {
            net = 0 - sold[stock]
            print stock ",0," sold[stock] "," net ",false,true"
        }
    }
}' temp_stock_analysis/bob_counts.csv > temp_stock_analysis/bob_stock_summary.csv
